112	// readFrame reads one server (unmasked) frame.
113	func (c *wsClient) readFrame() (fin bool, opcode byte, payload []byte) {
114		c.t.Helper()
115		header := make([]byte, 2)
116		if _, err := io.ReadFull(c.br, header); err != nil {
117			c.t.Fatalf("read frame header: %v", err)
118		}
119		fin = header[0]&0x80 != 0
120		opcode = header[0] & 0x0F
121		length := int64(header[1] & 0x7F)
122		switch length {
123		case 126:
124			var ext [2]byte
125			if _, err := io.ReadFull(c.br, ext[:]); err != nil {
126				c.t.Fatalf("read ext len: %v", err)
127			}
128			length = int64(binary.BigEndian.Uint16(ext[:]))
