131			if _, err := io.ReadFull(c.br, ext[:]); err != nil {
132				c.t.Fatalf("read ext len: %v", err)
133			}
134			length = int64(binary.BigEndian.Uint64(ext[:]))
135		}
136		payload = make([]byte, length)
137		if length > 0 {
