186	// readChange reads the next complete text message and decodes one change row.
187	// The server only ever sends whole (FIN) text frames; pongs are skipped.
188	func (c *wsClient) readChange() events.ListedChange {
189		c.t.Helper()
190		for {
191			fin, opcode, payload := c.readFrame()
192			switch opcode {
193			case wsOpcodeText:
194				if !fin {
195					c.t.Fatal("server sent a fragmented text frame")
196				}
197				var change events.ListedChange
198				if err := json.Unmarshal(payload, &change); err != nil {
199					c.t.Fatalf("text frame is not a change row: %s (%v)", payload, err)
200				}
201				return change
202			case wsOpcodePong:
203				continue
204			case wsOpcodeClose:
