223	// sendMasked writes one masked client frame.
224	func (c *wsClient) sendMasked(opcode byte, payload []byte) {
225		c.t.Helper()
226		mask := make([]byte, 4)
227		_, _ = rand.Read(mask)
228		masked := append([]byte(nil), payload...)
229		for i := range masked {
230			masked[i] ^= mask[i%4]
231		}
232		var header []byte
233		b0 := byte(0x80) | opcode
234		switch {
235		case len(payload) <= 125:
236			header = append(header, b0, 0x80|byte(len(payload)))
237		case len(payload) <= 65535:
238			header = append(header, b0, 0x80|126)
239			ext := make([]byte, 2)
240			binary.BigEndian.PutUint16(ext, uint16(len(payload)))
241			header = append(header, ext...)
242		default:
243			header = append(header, b0, 0x80|127)
244			ext := make([]byte, 8)
245			binary.BigEndian.PutUint64(ext, uint64(len(payload)))
246			header = append(header, ext...)
247		}
248		header = append(header, mask...)
249		if _, err := c.conn.Write(header); err != nil {
250			c.t.Fatalf("write frame header: %v", err)
251		}
252		if len(masked) > 0 {
253			if _, err := c.conn.Write(masked); err != nil {
254				c.t.Fatalf("write frame payload: %v", err)
255			}
256		}
257	}
